<?php declare(strict_types=1); require __DIR__ . '/admin.php'; requireAdmin($database); $message = null; if ($_SERVER['REQUEST_METHOD'] === 'POST') { $statement = $database->prepare('INSERT INTO products (category_id, name, slug, description, price, stock_quantity) VALUES (:category_id, :name, :slug, :description, :price, :stock)'); $statement->execute(['category_id' => (int) ($_POST['category_id'] ?? 0) ?: null, 'name' => trim((string) $_POST['name']), 'slug' => trim((string) $_POST['slug']), 'description' => trim((string) $_POST['description']), 'price' => (float) $_POST['price'], 'stock' => (int) $_POST['stock']]); $message = 'Product created.'; } $categories = $database->query('SELECT id, name FROM categories ORDER BY name')->fetchAll(); $products = $database->query('SELECT id, name, price, stock_quantity, is_active FROM products ORDER BY created_at DESC')->fetchAll(); adminHeader('Manage products'); ?><h1>Manage products</h1><?php if ($message): ?><p><?= $message ?></p><?php endif; ?><form method="post"><input name="name" placeholder="Name" required><input name="slug" placeholder="slug" required><input name="description" placeholder="Description"><input name="price" type="number" step="0.01" min="0" required><input name="stock" type="number" min="0" required><select name="category_id"><option value="0">No category</option><?php foreach ($categories as $category): ?><option value="<?= (int) $category['id'] ?>"><?= htmlspecialchars($category['name'], ENT_QUOTES, 'UTF-8') ?></option><?php endforeach; ?></select><button>Create product</button></form><ul><?php foreach ($products as $product): ?><li><?= htmlspecialchars($product['name'], ENT_QUOTES, 'UTF-8') ?> | ₹<?= number_format((float) $product['price'], 2) ?> | stock <?= (int) $product['stock_quantity'] ?></li><?php endforeach; ?></ul><?php adminFooter(); ?>
